#!/usr/bin/env python3
"""Builds results.md from tables.md (generated by tables.py) and notes.md
(written by hand): notes.md's text before its first `## ` heading comes
first; then every `## ` section of tables.md, each followed by the notes
section with the same heading; then the notes sections tables.md lacks."""

from pathlib import Path

RES = Path(__file__).resolve().parent.parent


def sections(text):
    head, out, cur = [], [], None
    for line in text.splitlines(keepends=True):
        if line.startswith("## "):
            cur = [line.strip(), []]
            out.append(cur)
        elif cur is None:
            head.append(line)
        else:
            cur[1].append(line)
    return "".join(head), [(h, "".join(b)) for h, b in out]


def main():
    _, tables = sections((RES / "tables.md").read_text())
    front, notes = sections((Path(__file__).parent / "notes.md").read_text())
    by = dict(notes)
    parts = [front]
    for h, body in tables:
        parts.append(f"{h}\n{body.rstrip()}\n\n")
        if h in by:
            parts.append(by.pop(h).strip() + "\n\n")
    for h, body in notes:
        if h in by:
            parts.append(f"{h}\n\n{body.strip()}\n\n")
    print("".join(parts).rstrip())


if __name__ == "__main__":
    main()
